//! INT 10h: our own VGA text BIOS for the emulated VGA (vga.c).  Text modes 0-3/7 are served as 80x25 colour,
//! graphics modes 0Dh/0Eh/10h are not provided, 12h (640x480x16) and 13h (320x200x256) can be selected but get no
//! BIOS character output (Windows programs the VGA itself).  State lives in the BDA exactly where DOS looks.
//! Font data = guest ROM (font16.bin / font8.bin generated by tools/gen_font.py).
use crate::syms::*;
use crate::*;

const COLS: u32 = 80;
const PAGE_BYTES: u32 = 0x1000;
const TEXT: u32 = 0x18000; // B8000 as an offset into the VGA window (A0000)

// ---- hardware access
fn out(port: u32, v: u32) { (env().pio_out)(port, 1, v) }
fn inp(port: u32) -> u32 { (env().pio_in)(port, 1) }
fn vr(off: u32) -> u8 { (env().vga_rd)(off) }
fn vw(off: u32, v: u8) { (env().vga_wr)(off, v) }
fn seq(i: u32, v: u32) { out(0x3C4, i); out(0x3C5, v); }
fn gc(i: u32, v: u32) { out(0x3CE, i); out(0x3CF, v); }
fn crtc(i: u32, v: u32) { out(0x3D4, i); out(0x3D5, v); }
fn attr(i: u32, v: u32) { inp(0x3DA); out(0x3C0, i); out(0x3C0, v); }
fn attr_read(i: u32) -> u32 { inp(0x3DA); out(0x3C0, i | 0x20); let v = inp(0x3C1); inp(0x3DA); out(0x3C0, 0x20); v }

struct ModeRegs {
    misc: u8,
    seq: [u8; 4], // SR1..SR4
    crtc: [u8; 25],
    gc: [u8; 9],
    ac: [u8; 21],
}

const TEXT_REGS: ModeRegs = ModeRegs {
    misc: 0x67,
    seq: [0x00, 0x03, 0x00, 0x02],
    crtc: [0x5F, 0x4F, 0x50, 0x82, 0x55, 0x81, 0xBF, 0x1F, 0x00, 0x4F, 0x0D, 0x0E, 0x00, 0x00, 0x00, 0x00, 0x9C, 0x8E, 0x8F, 0x28, 0x1F, 0x96, 0xB9, 0xA3, 0xFF],
    gc: [0x00, 0x00, 0x00, 0x00, 0x00, 0x10, 0x0E, 0x00, 0xFF],
    ac: [0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x14, 0x07, 0x38, 0x39, 0x3A, 0x3B, 0x3C, 0x3D, 0x3E, 0x3F, 0x0C, 0x00, 0x0F, 0x08, 0x00],
};
const MODE12_REGS: ModeRegs = ModeRegs {
    misc: 0xE3,
    seq: [0x01, 0x0F, 0x00, 0x06],
    crtc: [0x5F, 0x4F, 0x50, 0x82, 0x54, 0x80, 0x0B, 0x3E, 0x00, 0x40, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0xEA, 0x8C, 0xDF, 0x28, 0x00, 0xE7, 0x04, 0xE3, 0xFF],
    gc: [0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x05, 0x0F, 0xFF],
    ac: [0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x14, 0x07, 0x38, 0x39, 0x3A, 0x3B, 0x3C, 0x3D, 0x3E, 0x3F, 0x01, 0x00, 0x0F, 0x00, 0x00],
};
const MODE13_REGS: ModeRegs = ModeRegs {
    misc: 0x63,
    seq: [0x01, 0x0F, 0x00, 0x0E],
    crtc: [0x5F, 0x4F, 0x50, 0x82, 0x54, 0x80, 0xBF, 0x1F, 0x00, 0x41, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x9C, 0x8E, 0x8F, 0x28, 0x40, 0x96, 0xB9, 0xA3, 0xFF],
    gc: [0x00, 0x00, 0x00, 0x00, 0x00, 0x40, 0x05, 0x0F, 0xFF],
    ac: [0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x0E, 0x0F, 0x41, 0x00, 0x0F, 0x00, 0x00],
};

fn program(r: &ModeRegs) {
    seq(0, 1); // synchronous reset
    out(0x3C2, r.misc as u32);
    for i in 0..4 { seq(1 + i as u32, r.seq[i] as u32); }
    seq(0, 3);
    crtc(0x11, (r.crtc[0x11] & 0x7F) as u32); // unlock CR0-7
    for i in 0..25 { crtc(i as u32, r.crtc[i] as u32); }
    for i in 0..9 { gc(i as u32, r.gc[i] as u32); }
    for i in 0..21 { attr(i as u32, r.ac[i] as u32); }
    inp(0x3DA);
    out(0x3C0, 0x20); // video on
}

fn dac(i: u32, r: u32, g: u32, b: u32) { out(0x3C8, i); out(0x3C9, r); out(0x3C9, g); out(0x3C9, b); }

fn load_dac(mode13: bool) {
    // entries 0-63: the EGA 64-colour set (text and 16-colour modes); mode 13h: CGA 16 + grey ramp + colour ramps
    if !mode13 {
        for n in 0..64u32 {
            let r = ((n >> 2) & 1) * 42 + ((n >> 5) & 1) * 21;
            let g = ((n >> 1) & 1) * 42 + ((n >> 4) & 1) * 21;
            let b = (n & 1) * 42 + ((n >> 3) & 1) * 21;
            dac(n, r, g, b);
        }
        for n in 64..256 { dac(n, 0, 0, 0); }
    } else {
        for n in 0..16u32 {
            let br = if n & 8 != 0 { 21 } else { 0 };
            let (mut r, mut g, mut b) = (((n >> 2) & 1) * 42 + br, ((n >> 1) & 1) * 42 + br, (n & 1) * 42 + br);
            if n == 6 { g = 21; }
            if n == 8 { r = 21; g = 21; b = 21; }
            dac(n, r, g, b);
        }
        let grey = [0u32, 5, 8, 11, 14, 17, 20, 24, 28, 32, 36, 40, 45, 50, 56, 63];
        for (i, v) in grey.iter().enumerate() { dac(16 + i as u32, *v, *v, *v); }
        for n in 32..256u32 { let h = n - 32; dac(n, (h * 3) & 63, (h * 5) & 63, (h * 7) & 63); }
    }
}

fn font_ptr16() -> u32 { 0xF0000 + FONT16 as u32 }

/// load 256 glyphs (8x16) into plane 2 and restore text addressing
fn load_font() {
    seq(2, 0x04);
    seq(4, 0x07);
    gc(4, 0x02);
    gc(5, 0x00);
    gc(6, 0x04);
    let rom = unsafe { core::slice::from_raw_parts(env().mem.add(font_ptr16() as usize), 4096) };
    for c in 0..256usize {
        for y in 0..16usize { vw((c * 32 + y) as u32, rom[c * 16 + y]); }
        for y in 16..32usize { vw((c * 32 + y) as u32, 0); }
    }
    seq(2, 0x03);
    seq(4, 0x03);
    gc(4, 0x00);
    gc(5, 0x10);
    gc(6, 0x0E);
}

fn set_cursor_hw(cx: &Cx, page: u32) {
    if page != cx.bda8(0x62) as u32 { return; }
    let pos = cx.bda16(0x50 + page * 2);
    let off = cx.bda16(0x4E) as u32 / 2 + (pos >> 8) as u32 * COLS + (pos & 0xFF) as u32;
    crtc(0x0E, off >> 8);
    crtc(0x0F, off & 0xFF);
}

fn set_mode(cx: &mut Cx, mode: u8) {
    let keep = mode & 0x80 != 0;
    let m = mode & 0x7F;
    let (regs, mode13) = match m {
        0x12 => (&MODE12_REGS, false),
        0x13 => (&MODE13_REGS, true),
        _ => (&TEXT_REGS, false),
    };
    let text = m != 0x12 && m != 0x13;
    (env().vbe_w)(4, 0); // dispi off: legacy registers rule
    program(regs);
    load_dac(mode13);
    if text { load_font(); }
    cx.set_bda8(0x49, if text { if m == 7 { 3 } else { m.min(3) } } else { m });
    cx.set_bda16(0x4A, if text { COLS as u16 } else if m == 0x13 { 40 } else { 80 });
    cx.set_bda16(0x4C, if text { PAGE_BYTES as u16 } else { 0xFA00 });
    cx.set_bda16(0x4E, 0);
    for p in 0..8 { cx.set_bda16(0x50 + p * 2, 0); }
    cx.set_bda16(0x60, 0x0607);
    cx.set_bda8(0x62, 0);
    cx.set_bda16(0x63, 0x3D4);
    cx.set_bda8(0x65, 0);
    cx.set_bda8(0x66, 0);
    cx.set_bda8(0x84, if text { 24 } else if m == 0x12 { 29 } else { 24 });
    cx.set_bda16(0x85, if text { 16 } else if m == 0x12 { 16 } else { 8 });
    cx.set_bda8(0x87, if keep { 0xE0 } else { 0x60 });
    cx.set_bda8(0x88, 0xF9);
    cx.set_bda8(0x89, 0x51);
    cx.set_bda8(0x8A, 0x08);
    if !keep {
        if text {
            for i in 0..0x4000u32 { vw(TEXT + i * 2, 0x20); vw(TEXT + i * 2 + 1, 0x07); }
        } else {
            seq(2, 0x0F);
            for i in 0..0x10000u32 { vw(i, 0); }
        }
    }
    crtc(0x0A, 0x0D); // cursor 0Dh-0Eh in the 16-line cell
    crtc(0x0B, 0x0E);
    crtc(0x0C, 0);
    crtc(0x0D, 0);
    set_cursor_hw(cx, 0);
}

// ---- text helpers
fn cell(cx: &Cx, page: u32, row: u32, col: u32) -> u32 { TEXT + page * PAGE_BYTES + (row * COLS + col) * 2 }
fn rows(cx: &Cx) -> u32 { cx.bda8(0x84) as u32 + 1 }
fn put(cx: &Cx, page: u32, row: u32, col: u32, ch: u8, at: Option<u8>) {
    let o = cell(cx, page, row, col);
    vw(o, ch);
    if let Some(a) = at { vw(o + 1, a); }
}

fn scroll(cx: &Cx, up: bool, n: u32, at: u8, top: u32, left: u32, bot: u32, right: u32) {
    let page = cx.bda8(0x62) as u32;
    // clamp to the screen and reject inverted windows (garbage registers from DOS error paths wrapped to ~4e9 iterations)
    let bot = bot.min(cx.bda8(0x84) as u32);
    let right = right.min((cx.bda16(0x4A) as u32).saturating_sub(1));
    if bot < top || right < left { return; }
    let h = bot - top + 1;
    let n = if n == 0 || n > h { h } else { n };
    let w = right - left + 1;
    if n == h {
        for r in top..=bot { for c in left..=right { put(cx, page, r, c, 0x20, Some(at)); } }
        return;
    }
    if up {
        for r in top..=bot - n {
            for c in left..=right {
                let s = cell(cx, page, r + n, c);
                let d = cell(cx, page, r, c);
                vw(d, vr(s)); vw(d + 1, vr(s + 1));
            }
        }
        for r in (bot + 1 - n)..=bot { for c in left..left + w { put(cx, page, r, c, 0x20, Some(at)); } }
    } else {
        for r in ((top + n)..=bot).rev() {
            for c in left..=right {
                let s = cell(cx, page, r - n, c);
                let d = cell(cx, page, r, c);
                vw(d, vr(s)); vw(d + 1, vr(s + 1));
            }
        }
        for r in top..top + n { for c in left..left + w { put(cx, page, r, c, 0x20, Some(at)); } }
    }
}

fn teletype(cx: &mut Cx, ch: u8, page: u32) {
    let pos = cx.bda16(0x50 + page * 2);
    let (mut col, mut row) = ((pos & 0xFF) as u32, (pos >> 8) as u32);
    match ch {
        7 => {}
        8 => { if col > 0 { col -= 1; } }
        10 => row += 1,
        13 => col = 0,
        _ => {
            put(cx, page, row, col, ch, None);
            col += 1;
            if col >= COLS { col = 0; row += 1; }
        }
    }
    let nrows = rows(cx);
    if row >= nrows {
        scroll(cx, true, 1, 0x07, 0, 0, nrows - 1, COLS - 1);
        row = nrows - 1;
    }
    cx.set_bda16(0x50 + page * 2, ((row << 8) | col) as u16);
}

pub fn int10(cx: &mut Cx) {
    let ah = cx.ah();
    let al = cx.al();
    let page_cur = cx.bda8(0x62) as u32;
    let text = cx.bda8(0x49) <= 3 || cx.bda8(0x49) == 7;
    match ah {
        0x00 => set_mode(cx, al),
        0x01 => {
            let v = cx.cx();
            cx.set_bda16(0x60, v);
            let h = cx.bda16(0x85);
            let (s, e) = if h > 8 && (v & 0xFF) < 8 { (((v >> 8) & 0x3F) + 7, (v & 0xFF) + 7) } else { ((v >> 8) & 0x3F, v & 0xFF) };
            crtc(0x0A, (s as u32) | ((v as u32) >> 8 & 0x20));
            crtc(0x0B, e as u32);
        }
        0x02 => {
            let page = (cx.bx() >> 8) as u32 & 7;
            cx.set_bda16(0x50 + page * 2, cx.dx());
            set_cursor_hw(cx, page);
        }
        0x03 => {
            let page = (cx.bx() >> 8) as u32 & 7;
            let (p, s) = (cx.bda16(0x50 + page * 2), cx.bda16(0x60));
            cx.set16(EDX, p);
            cx.set16(ECX, s);
            cx.set_ah(0);
        }
        0x05 => {
            let p = (al & 7) as u32;
            cx.set_bda8(0x62, p as u8);
            cx.set_bda16(0x4E, (p * PAGE_BYTES) as u16);
            let o = p * PAGE_BYTES / 2;
            crtc(0x0C, o >> 8);
            crtc(0x0D, o & 0xFF);
            set_cursor_hw(cx, p);
        }
        0x06 | 0x07 if text => {
            let at = (cx.bx() >> 8) as u8;
            let (top, left) = ((cx.cx() >> 8) as u32, (cx.cx() & 0xFF) as u32);
            let (bot, right) = (((cx.dx() >> 8) as u32).min(rows(cx) - 1), ((cx.dx() & 0xFF) as u32).min(COLS - 1));
            if bot >= top && right >= left { scroll(cx, ah == 6, al as u32, at, top, left, bot, right); }
        }
        0x08 if text => {
            let page = (cx.bx() >> 8) as u32 & 7;
            let pos = cx.bda16(0x50 + page * 2);
            let o = cell(cx, page, (pos >> 8) as u32, (pos & 0xFF) as u32);
            cx.set16(EAX, ((vr(o + 1) as u16) << 8) | vr(o) as u16);
        }
        0x09 | 0x0A if text => {
            let page = (cx.bx() >> 8) as u32 & 7;
            let pos = cx.bda16(0x50 + page * 2);
            let (mut row, mut col) = ((pos >> 8) as u32, (pos & 0xFF) as u32);
            let at = if ah == 9 { Some(cx.bx() as u8) } else { None };
            for _ in 0..cx.cx() {
                if row >= rows(cx) { break; }
                put(cx, page, row, col, al, at);
                col += 1;
                if col >= COLS { col = 0; row += 1; }
            }
        }
        0x0C if cx.bda8(0x49) == 0x13 => {
            let (x, y) = (cx.cx() as u32, cx.dx() as u32);
            if x < 320 && y < 200 { vw(y * 320 + x, al); }
        }
        0x0D if cx.bda8(0x49) == 0x13 => {
            let (x, y) = (cx.cx() as u32, cx.dx() as u32);
            cx.set_al(if x < 320 && y < 200 { vr(y * 320 + x) } else { 0 });
        }
        0x0E => {
            if text { teletype(cx, al, page_cur); set_cursor_hw(cx, page_cur); }
        }
        0x0F => {
            cx.set_ah(cx.bda16(0x4A) as u8);
            cx.set_al(cx.bda8(0x49) | (cx.bda8(0x87) & 0x80));
            cx.set32(EBX, (cx.r(EBX) & 0xFFFF_00FF) | (page_cur << 8));
        }
        0x10 => palette(cx),
        0x11 => font(cx),
        0x12 => match cx.bx() as u8 {
            0x10 => { cx.set16(EBX, 0x0003); cx.set16(ECX, 0x0009); }
            0x30..=0x36 => cx.set_al(0x12),
            _ => {}
        },
        0x13 if text => {
            let page = (cx.bx() >> 8) as u32 & 7;
            let mut at = cx.bx() as u8;
            let mut p = cx.bda16(0x50 + page * 2);
            let (mut row, mut col) = (cx.dh() as u32, cx.dl() as u32);
            let mut a = cx.seg(ES).wrapping_add(cx.r(EBP) & 0xFFFF);
            let save = p;
            if al & 0x04 != 0 || true {
                for _ in 0..cx.cx() {
                    let ch = cx.rd8(a);
                    a = a.wrapping_add(1);
                    if al & 2 != 0 { at = cx.rd8(a); a = a.wrapping_add(1); }
                    match ch {
                        7 => {}
                        8 => { if col > 0 { col -= 1; } }
                        10 => row += 1,
                        13 => col = 0,
                        _ => { put(cx, page, row, col, ch, Some(at)); col += 1; if col >= COLS { col = 0; row += 1; } }
                    }
                    if row >= rows(cx) { scroll(cx, true, 1, 0x07, 0, 0, rows(cx) - 1, COLS - 1); row = rows(cx) - 1; }
                }
                p = ((row << 8) | col) as u16;
            }
            if al & 1 != 0 { cx.set_bda16(0x50 + page * 2, p); set_cursor_hw(cx, page); } else { cx.set_bda16(0x50 + page * 2, save); }
        }
        0x1A => {
            if al == 0 { cx.set_al(0x1A); cx.set16(EBX, 0x0008); }
        }
        0x1B => {
            let d = cx.seg(ES).wrapping_add(cx.di() as u32);
            for i in 0..64 { cx.wr8(d + i, 0); }
            cx.wr32(d, 0xF0000 + 0x0F00); // static functionality table pointer (zeros)
            cx.wr8(d + 4, cx.bda8(0x49));
            cx.wr16(d + 5, cx.bda16(0x4A));
            cx.wr16(d + 0x22, cx.bda8(0x84) as u16 + 1);
            cx.set_al(0x1B);
        }
        0x4F => vbe(cx),
        _ => {}
    }
}

fn palette(cx: &mut Cx) {
    let al = cx.al();
    match al {
        0x00 => attr(cx.bx() as u32 >> 0 & 0xFF, (cx.bx() >> 8) as u32 | 0),
        0x01 => attr(0x11, (cx.bx() >> 8) as u32),
        0x02 => {
            let a = cx.seg(ES).wrapping_add(cx.dx() as u32);
            for i in 0..16 { attr(i, cx.rd8(a + i) as u32); }
            attr(0x11, cx.rd8(a + 16) as u32);
        }
        0x03 => {
            let cur = attr_read(0x10);
            attr(0x10, if cx.bx() as u8 & 1 != 0 { cur | 8 } else { cur & !8 });
        }
        0x07 => { let v = attr_read(cx.bx() as u32 & 0xFF); cx.set32(EBX, (cx.r(EBX) & 0xFFFF_00FF) | v << 8); }
        0x08 => { let v = attr_read(0x11); cx.set32(EBX, (cx.r(EBX) & 0xFFFF_00FF) | v << 8); }
        0x10 => dac(cx.bx() as u32 & 0xFF, (cx.dx() >> 8) as u32 & 63, (cx.cx() >> 8) as u32 & 63, cx.cx() as u32 & 63),
        0x12 => {
            let a = cx.seg(ES).wrapping_add(cx.dx() as u32);
            out(0x3C8, cx.bx() as u32 & 0xFF);
            for i in 0..cx.cx() as u32 * 3 { out(0x3C9, cx.rd8(a + i) as u32 & 63); }
        }
        0x15 => {
            out(0x3C7, cx.bx() as u32 & 0xFF);
            let (r, g, b) = (inp(0x3C9), inp(0x3C9), inp(0x3C9));
            cx.set_dh(r as u8); cx.set_ch(g as u8); cx.set_cl(b as u8);
        }
        0x17 => {
            let a = cx.seg(ES).wrapping_add(cx.dx() as u32);
            out(0x3C7, cx.bx() as u32 & 0xFF);
            for i in 0..cx.cx() as u32 * 3 { cx.wr8(a + i, inp(0x3C9) as u8); }
        }
        0x1A => { cx.set32(EBX, 0); }
        _ => {}
    }
}

fn font(cx: &mut Cx) {
    match cx.al() {
        0x04 | 0x14 | 0x00 | 0x10 | 0x01 | 0x11 | 0x02 | 0x12 => { load_font(); }
        0x30 => {
            let bh = (cx.bx() >> 8) as u8;
            let (seg, off) = match bh {
                0 => (0u32, cx.rd16(0x1F * 4) as u32),
                1 => (0, 0),
                3 | 4 => (0xF000, FONT8 as u32 + if bh == 4 { 1024 } else { 0 }),
                _ => (0xF000, FONT16 as u32),
            };
            let _ = seg;
            cx.set_cx_font(bh, off);
        }
        _ => {}
    }
}

impl Cx {
    /// AL=30h result: CX = bytes per character, DL = rows - 1, ES:BP = font pointer (ES = F000 is loaded by the guest stub)
    fn set_cx_font(&mut self, bh: u8, off: u32) {
        let h = if bh == 3 || bh == 4 { 8 } else { 16 };
        self.set16(ECX, h);
        self.set_dl(self.bda8(0x84));
        self.set16(EBP, off as u16);
    }
}

// ---------------- VBE 2.0 on the Bochs dispi registers of vga.c (idea and mode table from the RED team) ----------------
const VMODES: [(u16, u16, u16, u8); 16] = [
    (0x100, 640, 400, 8), (0x101, 640, 480, 8), (0x103, 800, 600, 8), (0x105, 1024, 768, 8), (0x107, 1280, 1024, 8),
    (0x110, 640, 480, 15), (0x111, 640, 480, 16), (0x112, 640, 480, 32), (0x113, 800, 600, 15), (0x114, 800, 600, 16),
    (0x115, 800, 600, 32), (0x116, 1024, 768, 15), (0x117, 1024, 768, 16), (0x118, 1024, 768, 32),
    (0x160, 1280, 800, 8), (0x161, 1280, 800, 16),
];

fn vbe(cx: &mut Cx) {
    let e = env();
    let a = cx.seg(ES).wrapping_add(cx.di() as u32);
    let oem = 0xF000_0000u32 | OEM as u32;
    match cx.al() {
        0x00 => {
            let want2 = cx.rd32(a) == 0x3245_4256; // 'VBE2'
            for i in 0..(if want2 { 512 } else { 256 }) { cx.wr8(a + i, 0); }
            for (i, b) in b"VESA".iter().enumerate() { cx.wr8(a + i as u32, *b); }
            cx.wr16(a + 4, 0x0200);
            cx.wr32(a + 6, oem);
            cx.wr32(a + 10, 1);
            cx.wr32(a + 14, ((cx.st[16 + ES]) << 16) | (cx.di() as u32 + 0x100)); // mode list lives in the block itself
            for (i, m) in VMODES.iter().enumerate() { cx.wr16(a + 0x100 + i as u32 * 2, m.0); }
            cx.wr16(a + 0x100 + VMODES.len() as u32 * 2, 0xFFFF);
            cx.wr16(a + 18, (e.vga_ram >> 16) as u16);
            if want2 {
                cx.wr16(a + 20, 0x0100);
                cx.wr32(a + 22, oem); cx.wr32(a + 26, oem); cx.wr32(a + 30, oem);
                cx.wr16(a + 34, 0x0100);
            }
            cx.set16(EAX, 0x004F);
        }
        0x01 => {
            let mode = cx.cx() & 0x1FF;
            match VMODES.iter().find(|m| m.0 == mode) {
                None => cx.set16(EAX, 0x014F),
                Some(&(_, w, h, bpp)) => {
                    for i in 0..256 { cx.wr8(a + i, 0); }
                    cx.wr16(a, 0x009B); cx.wr8(a + 2, 0x07); cx.wr16(a + 4, 64); cx.wr16(a + 6, 64); cx.wr16(a + 8, 0xA000);
                    cx.wr16(a + 16, (w as u32 * ((bpp as u32 + 7) / 8)) as u16);
                    cx.wr16(a + 18, w); cx.wr16(a + 20, h);
                    cx.wr8(a + 22, 8); cx.wr8(a + 23, 16); cx.wr8(a + 24, 1); cx.wr8(a + 25, bpp); cx.wr8(a + 26, 1);
                    cx.wr8(a + 27, if bpp == 8 { 4 } else { 6 });
                    let (rs, rp, gs, gp, bs, bp) = match bpp { 15 => (5, 10, 5, 5, 5, 0), 16 => (5, 11, 6, 5, 5, 0), 8 => (0, 0, 0, 0, 0, 0), _ => (8, 16, 8, 8, 8, 0) };
                    cx.wr8(a + 31, rs); cx.wr8(a + 32, rp); cx.wr8(a + 33, gs); cx.wr8(a + 34, gp); cx.wr8(a + 35, bs); cx.wr8(a + 36, bp);
                    if bpp == 32 { cx.wr8(a + 37, 8); cx.wr8(a + 38, 24); }
                    cx.wr32(a + 40, e.vga_lfb);
                    cx.set16(EAX, 0x004F);
                }
            }
        }
        0x02 => {
            let mode = cx.bx();
            let (lfb, noclear, id) = (mode & 0x4000 != 0, mode & 0x8000 != 0, mode & 0x1FF);
            if id < 0x100 {
                set_mode(cx, id as u8 | if noclear { 0x80 } else { 0 });
                cx.set16(EAX, 0x004F);
                return;
            }
            match VMODES.iter().find(|m| m.0 == id) {
                None => cx.set16(EAX, 0x014F),
                Some(&(_, w, h, bpp)) => {
                    (e.vbe_w)(4, 0);
                    (e.vbe_w)(1, w); (e.vbe_w)(2, h); (e.vbe_w)(3, bpp as u16);
                    (e.vbe_w)(4, 0x01 | if lfb { 0x40 } else { 0 } | if noclear { 0x80 } else { 0 });
                    cx.set_bda8(0x49, 0x6A);
                    cx.set_bda16(0xB0, id | if lfb { 0x4000 } else { 0 });
                    cx.set16(EAX, 0x004F);
                }
            }
        }
        0x03 => {
            let on = (e.vbe_r)(4) & 1 != 0;
            let m = if on { cx.bda16(0xB0) } else { cx.bda8(0x49) as u16 };
            cx.set16(EBX, m);
            cx.set16(EAX, 0x004F);
        }
        0x04 => { if cx.dl() == 0 { cx.set16(EBX, 0); } cx.set16(EAX, 0x004F); }
        0x05 => {
            if (cx.bx() >> 8) == 0 { (e.vbe_w)(5, cx.dx()); } else { let b = (e.vbe_r)(5); cx.set16(EDX, b); }
            cx.set16(EAX, 0x004F);
        }
        0x06 => {
            let bpp = ((e.vbe_r)(3) as u32).max(8);
            match cx.bx() as u8 { 0 => (e.vbe_w)(6, cx.cx()), 2 => (e.vbe_w)(6, (cx.cx() as u32 * 8 / bpp) as u16), _ => {} }
            let vw = (e.vbe_r)(6) as u32;
            cx.set16(EBX, (vw * bpp / 8) as u16);
            cx.set16(ECX, vw as u16);
            cx.set16(EDX, (e.vga_ram / (vw * bpp / 8).max(1)) as u16);
            cx.set16(EAX, 0x004F);
        }
        0x07 => {
            let bl = cx.bx() as u8;
            if bl == 0 || bl == 0x80 { (e.vbe_w)(8, cx.cx()); (e.vbe_w)(9, cx.dx()); }
            else { let x = (e.vbe_r)(8); let y = (e.vbe_r)(9); cx.set16(ECX, x); cx.set16(EDX, y); }
            cx.set16(EAX, 0x004F);
        }
        0x08 => {
            let en = (e.vbe_r)(4);
            if cx.bx() as u8 == 0 {
                let want8 = (cx.bx() >> 8) >= 8;
                (e.vbe_w)(4, if want8 { en | 0x20 } else { en & !0x20 });
                cx.set32(EBX, (cx.r(EBX) & 0xFFFF_00FF) | if want8 { 8 << 8 } else { 6 << 8 });
            } else {
                cx.set32(EBX, (cx.r(EBX) & 0xFFFF_00FF) | if en & 0x20 != 0 { 8 << 8 } else { 6 << 8 });
            }
            cx.set16(EAX, 0x004F);
        }
        0x09 => {
            let eight = (e.vbe_r)(4) & 0x20 != 0;
            let sh = if eight { 0 } else { 2 };
            let first = cx.dx() as u32;
            match cx.bx() as u8 {
                0 | 0x80 => for k in 0..cx.cx() as u32 { dac((first + k) & 0xFF, (cx.rd8(a + k * 4 + 2) >> sh) as u32, (cx.rd8(a + k * 4 + 1) >> sh) as u32, (cx.rd8(a + k * 4) >> sh) as u32); },
                1 => { out(0x3C7, first); for k in 0..cx.cx() as u32 { let (r, g, b) = (inp(0x3C9) as u8, inp(0x3C9) as u8, inp(0x3C9) as u8); cx.wr8(a + k * 4, b << sh); cx.wr8(a + k * 4 + 1, g << sh); cx.wr8(a + k * 4 + 2, r << sh); cx.wr8(a + k * 4 + 3, 0); } }
                _ => {}
            }
            cx.set16(EAX, 0x004F);
        }
        _ => cx.set16(EAX, 0x014F),
    }
}
